#!/usr/bin/env node
// Generates website/src/pages/changelog.md from the repository CHANGELOG.md.
// CHANGELOG.md is the single source of truth; this page is regenerated by
// `pnpm start` and `pnpm build` and is not committed.
// Each release is rendered as a collapsible card, newest first, with the
// latest release expanded by default.
// Usage: node scripts/sync-changelog.mjs

import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..", "..");
const SOURCE = join(ROOT, "CHANGELOG.md");
const TARGET = join(ROOT, "website", "src", "pages", "changelog.md");
const REPO = "MalpenZibo/ashell";

const MONTHS = [
  "January",
  "February",
  "March",
  "April",
  "May",
  "June",
  "July",
  "August",
  "September",
  "October",
  "November",
  "December",
];

function formatDate(iso) {
  const [year, month, day] = iso.split("-").map(Number);
  if (!year || !month || !day || month < 1 || month > 12) {
    return iso;
  }
  return `${MONTHS[month - 1]} ${day}, ${year}`;
}

// The page is compiled as MDX, where `<` opens a JSX tag and `{` opens a JS
// expression. Release notes are generated from pull request titles, so their
// content is not under our control: a title mentioning `Option<T>` or a
// `{token}` config placeholder would otherwise fail the site build and block
// the GitHub Pages deploy. Everything outside code is escaped; escaping too
// much only shows a literal character, so this direction of error is safe.

// Finds the closing run of exactly `length` backticks, per the CommonMark code
// span rule. Returns -1 when the run is never closed on this line.
function findCodeSpanEnd(line, from, length) {
  for (let i = from; i < line.length; i += 1) {
    if (line[i] !== "`") continue;
    let run = 0;
    while (line[i + run] === "`") run += 1;
    if (run === length) return i;
    i += run - 1;
  }
  return -1;
}

function escapeText(text) {
  return text
    .replace(/<(https?:\/\/[^>\s]+)>/g, "[$1]($1)")
    .replace(/<([^\s@<>]+@[^\s@<>]+\.[^\s@<>]+)>/g, "[$1](mailto:$1)")
    .replace(/</g, "&lt;")
    .replace(/\{/g, "&#123;")
    .replace(/\}/g, "&#125;");
}

// Escapes one line, leaving inline code spans untouched: MDX does not parse
// JSX inside them, and escaping there would show the entities literally.
function escapeLine(line) {
  let out = "";
  let i = 0;
  let text = "";
  while (i < line.length) {
    if (line[i] === "`") {
      let run = 0;
      while (line[i + run] === "`") run += 1;
      const end = findCodeSpanEnd(line, i + run, run);
      if (end !== -1) {
        out += escapeText(text);
        text = "";
        out += line.slice(i, end + run);
        i = end + run;
        continue;
      }
    }
    text += line[i];
    i += 1;
  }
  return out + escapeText(text);
}

function escapeMdx(markdown) {
  let fence = null;
  return markdown
    .split("\n")
    .map((line) => {
      const match = /^ {0,3}(`{3,}|~{3,})(.*)$/.exec(line);
      if (fence !== null) {
        if (match && match[1][0] === fence[0] && match[1].length >= fence.length) {
          fence = null;
        }
        return line;
      }
      if (match) {
        fence = match[1];
        return line;
      }
      return escapeLine(line);
    })
    .join("\n");
}

let content = "";
try {
  content = readFileSync(SOURCE, "utf8");
} catch (error) {
  console.warn(`WARNING: could not read ${SOURCE}: ${error.message}`);
}

const headingRegex = /^## \[([\w.\-]+)\](?:\s+-\s+(\d{4}-\d{2}-\d{2}))?.*$/gm;
const releases = [];
let match;
while ((match = headingRegex.exec(content)) !== null) {
  releases.push({
    tag: match[1],
    date: match[2] ?? "",
    start: match.index,
    end: headingRegex.lastIndex,
  });
}

const sections = releases.map((release, index) => {
  const next = releases[index + 1];
  const body = escapeMdx(
    content.slice(release.end, next ? next.start : undefined),
  ).trim();
  const open = index === 0 ? " open" : "";
  return [
    `<details className="changelogRelease"${open}>`,
    `<summary><span className="changelogVersion">${release.tag}</span><span className="changelogDate">${formatDate(release.date)}</span></summary>`,
    "",
    body,
    "",
    `[View on GitHub](https://github.com/${REPO}/releases/tag/${release.tag})`,
    "",
    "</details>",
    "",
  ].join("\n");
});

// The navbar links to /changelog and onBrokenLinks is "throw", so the page has
// to exist even when there is nothing to put on it.
if (sections.length === 0) {
  console.warn("WARNING: no releases found in CHANGELOG.md");
  sections.push(
    `Release notes are available on [GitHub](https://github.com/${REPO}/releases).`,
    "",
  );
}

const page = [
  "---",
  "title: Changelog",
  "description: Release notes for ashell",
  "hide_table_of_contents: true",
  "---",
  "",
  "# Changelog",
  "",
  "Release notes for ashell.",
  "",
  ...sections,
].join("\n");

mkdirSync(dirname(TARGET), { recursive: true });
writeFileSync(TARGET, page);
console.log(
  `Synced CHANGELOG.md -> website/src/pages/changelog.md (${releases.length} releases)`,
);
